"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

// Frosted Glass Checkbox — unchecked is empty glass; checked lights up with the
// SAME material as the primary glass Button (--fg-fill-hover + --fg-shadow rim).

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

function Checkbox({
  className,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer inline-flex items-center justify-center h-5 w-5 shrink-0 rounded-[0.5rem]",
        "backdrop-blur-[var(--fg-blur)] backdrop-saturate-150 bg-[var(--fg-fill)]",
        "border border-[color:var(--fg-border)]",
        "shadow-[inset_0_0.0625rem_0_-0.0313rem_oklch(1_0_0/0.35)]",
        "transition-all duration-base",
        "hover:bg-[var(--fg-fill-hover)]",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-0",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "data-checked:bg-[var(--fg-fill-hover)] data-checked:text-foreground",
        "data-checked:shadow-[var(--fg-shadow)]",
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className={cn("flex items-center justify-center text-current")}
      >
        <Icon icon="tabler:check" className="size-full h-3.5 w-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}
Checkbox.displayName = "Checkbox"

export { Checkbox }
